const j = $input.first().json;
const pick = (...keys) => { for (const k of keys) { const v = j[k]; if (v !== undefined && v !== null && String(v).trim() !== '') return v; } return ''; };
const topic = String(pick('Topic for the Content', 'topic')).trim();
const referenceLink = String(pick('Reference Link', 'reference_link')).trim();
const wordRaw = String(pick('Word Limit', 'word_limit')).trim();
const hasWord = wordRaw !== '';
const wordLimit = hasWord ? parseInt(wordRaw, 10) : null;
const newsRaw = j['Current News'] !== undefined ? j['Current News'] : j.current_news;
const useNews = Array.isArray(newsRaw) ? newsRaw.length > 0 : (newsRaw !== undefined && newsRaw !== null && String(newsRaw).trim() !== '' && String(newsRaw).toLowerCase() !== 'false');
const fmtRaw = String(pick('Format', 'format')).trim();
// label -> {style, words}. words is the soft target sent when Word Limit is left empty.
// Legacy labels kept: a browser tab still open on the old form can submit them.
const FORMATS = {
  'LinkedIn Article Long (~1500 words)': { style: 'linkedin_article', words: 1500 },
  'LinkedIn Article Short (~800 words)': { style: 'linkedin_article_short', words: 800 },
  'Blog post (~1000 words)': { style: 'blog', words: 1000 },
  'LinkedIn article (~800 words)': { style: 'linkedin_article', words: 800 },
  'Newsletter section (~400 words)': { style: 'newsletter', words: 400 },
  'Standard prose (500-900 words)': { style: '', words: null },
  'Blog post': { style: 'blog', words: 1000 },
  'LinkedIn article': { style: 'linkedin_article', words: 800 },
  'Newsletter section': { style: 'newsletter', words: 400 },
  'Standard prose': { style: '', words: null }
};
const ALL_LABEL = 'All of the above (Blog + LinkedIn Long + LinkedIn Short + Newsletter)';
const ALL_LABELS = [ALL_LABEL, 'All of the above (Blog + LinkedIn Long + Newsletter + LinkedIn post)', 'All of the above (Blog + LinkedIn + Newsletter + Short post)'];
const ALL_SET = ['Blog post (~1000 words)', 'LinkedIn Article Long (~1500 words)', 'LinkedIn Article Short (~800 words)', 'Newsletter section (~400 words)'];
let formats = null;
if (ALL_LABELS.includes(fmtRaw)) formats = ALL_SET.map(l => ({ label: l, style: FORMATS[l].style, words: FORMATS[l].words }));
else if (fmtRaw === '') formats = [{ label: 'Standard prose (500-900 words)', style: '', words: null }];
else if (FORMATS[fmtRaw]) formats = [{ label: fmtRaw, style: FORMATS[fmtRaw].style, words: FORMATS[fmtRaw].words }];
let error = '';
if (topic.length < 3) error = 'Topic must be at least 3 characters.';
else if (hasWord && (!Number.isFinite(wordLimit) || wordLimit < 100 || wordLimit > 2000)) error = 'Word Limit must be empty or a number between 100 and 2000 (got "' + wordRaw + '").';
else if (referenceLink && !/^https?:\/\//i.test(referenceLink)) error = 'Reference Link must start with http:// or https://';
else if (!formats) error = 'Unknown format "' + fmtRaw + '" - the form options and the format map are out of sync.';
return [{ json: { topic: topic, referenceLink: referenceLink, wordLimit: wordLimit, useNews: useNews, formats: formats || [], multi: !!(formats && formats.length > 1), valid: !error, errorMessage: error } }];

const arts = [];
const errs = [];
try {
  const nd = $('Fetch NewsData').first().json;
  if (nd.error) errs.push('newsdata.io: ' + (nd.error.message || JSON.stringify(nd.error).slice(0, 200)));
  (nd.results || []).forEach(a => arts.push({ title: a.title, desc: a.description || '', src: a.source_id || a.source_name || 'newsdata', date: a.pubDate || '' }));
} catch (e) { errs.push('newsdata.io: ' + e.message); }
try {
  const na = $('Fetch NewsAPI').first().json;
  if (na.error) errs.push('newsapi.org: ' + (na.error.message || JSON.stringify(na.error).slice(0, 200)));
  (na.articles || []).forEach(a => arts.push({ title: a.title, desc: a.description || '', src: (a.source && a.source.name) || 'newsapi', date: a.publishedAt || '' }));
} catch (e) { errs.push('newsapi.org: ' + e.message); }
const seen = new Set();
const uniq = [];
for (const a of arts) {
  const k = (a.title || '').toLowerCase().slice(0, 80);
  if (!a.title || seen.has(k)) continue;
  seen.add(k);
  uniq.push(a);
  if (uniq.length >= 12) break;
}
const articlesText = uniq.map((a, i) => (i + 1) + '. [' + a.src + (a.date ? ', ' + String(a.date).slice(0, 10) : '') + '] ' + a.title + '\n   ' + String(a.desc).slice(0, 300)).join('\n');
return [{ json: { articleCount: uniq.length, articlesText: articlesText, newsErrors: errs, errorMessage: uniq.length === 0 ? ('No news articles found for this topic.' + (errs.length ? ' Errors: ' + errs.join(' | ') : '')) : '' } }];

const j = $input.first().json;
let content = '';
if (j.data && j.data.content) content = j.data.content;
else if (typeof j.content === 'string') content = j.content;
else if (typeof j.text === 'string') content = j.text;
content = String(content || '').trim();
let err = '';
if (j.error) err = 'Could not fetch the reference link: ' + (j.error.message || 'request failed');
else if (content.length < 200) err = 'The reference link returned too little readable text to work with.';
return [{ json: { articleText: content.slice(0, 15000), errorMessage: err, ok: !err } }];

const j = $input.first().json;
let raw = j.text !== undefined ? j.text : (j.response !== undefined ? j.response : (j.output !== undefined ? j.output : ''));
if (typeof raw !== 'string') raw = JSON.stringify(raw);
const cleaned = raw.replace(/```json\s*/gi, '').replace(/```/g, '').trim();
const m = cleaned.match(/\[[\s\S]*\]/);
let ideas = [];
try { ideas = JSON.parse(m ? m[0] : cleaned); } catch (e) { ideas = []; }
ideas = (Array.isArray(ideas) ? ideas : []).filter(i => i && typeof i.title === 'string' && i.title.trim()).slice(0, 5);
if (ideas.length < 3) {
  return [{ json: { ok: false, errorMessage: 'Idea generation did not return 3-5 usable ideas. Raw output started with: ' + cleaned.slice(0, 300) } }];
}
// Dropdown labels: truncate at a WORD boundary, never mid-word. The richer angles overflow a
// hard char cap and used to render as "...without hiring sp". Extract Selection maps the label
// back to the FULL idea, so nothing truncated here ever reaches the generator.
const LABEL_MAX = 180;
const options = ideas.map(i => {
  const title = String(i.title).trim();
  const angle = i.angle ? String(i.angle).trim() : '';
  const full = angle ? title + ' — ' + angle : title;
  if (full.length <= LABEL_MAX) return { option: full };
  const cut = full.slice(0, LABEL_MAX);
  const sp = cut.lastIndexOf(' ');
  return { option: cut.slice(0, sp > title.length ? sp : LABEL_MAX).trimEnd() + '…' };
});
const formJson = JSON.stringify([{ fieldLabel: 'Pick an idea', fieldType: 'dropdown', fieldOptions: { values: options }, requiredField: true }]);
return [{ json: { ok: true, ideas: ideas, formJson: formJson } }];

const j = $input.first().json;
const sel = String(j['Pick an idea'] !== undefined ? j['Pick an idea'] : (j.idea || '')).trim();
let ideas = [];
try { ideas = $('Parse Ideas').first().json.ideas || []; } catch (e) { ideas = []; }
// The dropdown label may be truncated for readability, so map it back to the FULL idea by
// title prefix (longest match wins, in case one title prefixes another). Never send a
// mid-sentence-truncated string to the generator.
const hit = ideas
  .filter(i => sel.startsWith(String(i.title).trim()))
  .sort((a, b) => String(b.title).length - String(a.title).length)[0] || null;
const title = hit ? String(hit.title).trim() : sel.split(' — ')[0].trim();
const angle = hit && hit.angle ? String(hit.angle).trim() : '';
if (!hit) {
  console.log('Extract Selection: no idea matched the picked label - falling back to the label text. sel=' + sel.slice(0, 120));
}
return [{ json: { ragTopic: angle ? title + ' — ' + angle : title, docTitle: title } }];

const j = $input.first().json;
const norm = $('Normalize Input').first().json;
const ragTopic = String(j.ragTopic || norm.topic).slice(0, 500);
const rawTitle = String(j.docTitle || norm.topic);
const baseTitle = (rawTitle.replace(/[\\/:*?"<>|]/g, '-').trim().slice(0, 90)) || 'DPDP Draft';
// ONE ITEM PER REQUESTED FORMAT: every downstream node (wake -> generate -> doc) runs per item,
// so 'All of the above' fans out to one API call and one Google Doc per format.
const formats = (Array.isArray(norm.formats) && norm.formats.length) ? norm.formats : [{ label: 'Standard prose (500-900 words)', style: '', words: null }];
return formats.map(f => ({ json: {
  ragTopic: ragTopic,
  docTitle: formats.length > 1 ? (baseTitle.slice(0, 70) + ' - ' + f.label.split(' (')[0]) : baseTitle,
  wordLimit: norm.wordLimit || f.words || null,
  referenceLink: String(norm.referenceLink || ''),
  style: f.style || '',
  formatLabel: f.label,
  // 'dpdp' unless Off-Topic Decision said otherwise, so every pre-existing path is unchanged.
  mode: j.mode || 'dpdp'
} }));

const items = $input.all();
const statusMap = {
  passed: 'PASSED automated citation checks',
  needs_human: 'NEEDS HUMAN REVIEW - automated checks flagged issues',
  no_grounded_source: 'NO GROUNDED SOURCE - the RAG system refused to draft this topic',
  ungrounded: 'NOT DPDP-GROUNDED - written WITHOUT the statutory corpus (no sources, no citations, no legal content)',
  needs_grounding: 'NEEDS DPDP GROUNDING - the topic could not be written honestly without legal claims; re-run it and TICK the "join DPDP" box'
};
// Superscript citation rendering (human's ask 2026-07-20): the VERIFIED bracketed citations
// are converted 1:1 into numbered superscripts plus a numbered reference list at the end.
// Deterministic string mapping only - no words are added or dropped, so cite_check's verdict
// still covers exactly the text that lands in the doc. Identical citations share a number.
const SUP = { '0': '⁰', '1': '¹', '2': '²', '3': '³', '4': '⁴', '5': '⁵', '6': '⁶', '7': '⁷', '8': '⁸', '9': '⁹' };
const sup = n => String(n).split('').map(d => SUP[d] || d).join('');
const ONE_CITE = /\[\s*\*{0,2}\s*(DPDP[^\[\]]*?)\s*\*{0,2}\s*\]/g;
const CITE_RUN = /[ \t]*(?:\[\s*\*{0,2}\s*DPDP[^\[\]]*?\s*\*{0,2}\s*\](?:[ \t]+(?=\[))?)+/g;
const out = [];
for (let i = 0; i < items.length; i++) {
  const r = items[i].json;
  if (!r || !r.review_status) {
    throw new Error('RAG API returned no usable response (review_status missing) for item ' + (i + 1) + ' - refusing to write a doc. Check the Call DPDP RAG API node.');
  }
  let p;
  try { p = $('Build Generate Payload').itemMatching(i).json; } catch (e) { p = $('Build Generate Payload').first().json; }
  const statusLabel = statusMap[r.review_status] || String(r.review_status);
  const wantStyle = p.style || '(default prose)';
  const gotStyle = (r.style === undefined) ? 'NOT CONFIRMED - the API is an older deploy and drafted default prose' : (r.style || '(default prose)');
  const lines = [];
  lines.push('=== REVIEW BANNER (do not publish until a human clears this) ===');
  lines.push('Status: ' + statusLabel);
  if (r.review_status === 'ungrounded' || r.review_status === 'needs_grounding') lines.push('*** NOT GROUNDED IN THE DPDP TEXTS. Written with no sources; cite_check did NOT run. This piece must not state what the law requires - if it does, do not publish it. ***');
  lines.push('Traceability score: ' + (r.traceability === null || r.traceability === undefined ? 'n/a' : r.traceability));
  lines.push('Provider: ' + (r.provider || 'n/a') + ' | Draft attempts: ' + (r.attempts !== undefined ? r.attempts : 'n/a'));
  lines.push('Format: requested ' + wantStyle + ' | drafted ' + gotStyle + ' | word target: ' + (p.wordLimit || 'default 500-900'));
  if (Array.isArray(r.fabricated) && r.fabricated.length) lines.push('FABRICATED CITATIONS FLAGGED: ' + r.fabricated.join('; '));
  if (Array.isArray(r.unsupported) && r.unsupported.length) lines.push('UNCITED CLAIMS (cite or delete before publishing): ' + r.unsupported.slice(0, 5).join(' | ') + (r.unsupported.length > 5 ? ' | (+' + (r.unsupported.length - 5) + ' more)' : ''));
  if (Array.isArray(r.not_in_force) && r.not_in_force.length) lines.push('CITED PROVISIONS NOT YET IN FORCE (copy must date them correctly): ' + r.not_in_force.join('; '));
  if (r.reference_hint) lines.push('Reference-link hint used: ' + r.reference_hint);
  lines.push('Requested topic: ' + p.ragTopic);
  lines.push('================================================================');
  lines.push('');
  const raw = String(r.content || '(no content returned)');
  const refOrder = [];
  const refNum = {};
  const rendered = raw.replace(CITE_RUN, run => {
    const nums = [];
    run.replace(ONE_CITE, (m, c) => {
      c = c.trim();
      if (!(c in refNum)) { refOrder.push(c); refNum[c] = refOrder.length; }
      nums.push(refNum[c]);
      return m;
    });
    return nums.map(sup).join(',');
  });
  lines.push(refOrder.length ? rendered : raw);
  const srcs = Array.isArray(r.sources) ? r.sources : [];
  const inRange = (c, s) => { const oc = c.lastIndexOf('('), os = s.citation.lastIndexOf('('); if (oc < 0 || os < 0 || c.slice(0, oc) !== s.citation.slice(0, os)) return false; const span = s.citation.slice(os + 1, s.citation.lastIndexOf(')')); const d = span.indexOf('-'); if (d < 0) return false; const lo = parseInt(span.slice(0, d), 10), hi = parseInt(span.slice(d + 1), 10), sub = c.slice(oc + 1, c.lastIndexOf(')')).trim(), n = parseInt(sub, 10); return Number.isInteger(lo) && Number.isInteger(hi) && Number.isInteger(n) && String(n) === sub && lo <= n && n <= hi; };
  const bySrc = c => srcs.filter(s => c === s.citation || c.startsWith(s.citation) || inRange(c, s)).sort((a, b) => b.citation.length - a.citation.length)[0];
  if (refOrder.length) {
    lines.push('');
    lines.push('=== REFERENCES (verify against the PDFs) ===');
    refOrder.forEach((c, k) => {
      const s = bySrc(c);
      lines.push((k + 1) + '. ' + c + (s ? ' [' + s.authority_status + '] - ' + s.source_ref + ', p.' + s.page : ''));
    });
    const uncited = srcs.filter(s => !refOrder.some(c => c === s.citation || c.startsWith(s.citation) || inRange(c, s)));
    if (uncited.length) lines.push('Also retrieved, not cited: ' + uncited.map(s => s.citation).join('; '));
  } else if (srcs.length) {
    lines.push('');
    lines.push('=== SOURCES (verify against the PDFs) ===');
    srcs.forEach(s => lines.push('- ' + s.citation + ' [' + s.authority_status + '] - ' + s.source_ref + ', p.' + s.page));
  }
  // Title prefix, not just a banner: in a Drive folder listing the title is all a reader sees.
  const prefix = r.review_status === 'ungrounded' ? '[NOT DPDP-GROUNDED] ' : (r.review_status === 'needs_grounding' ? '[NEEDS DPDP GROUNDING] ' : '');
  out.push({ json: { docText: lines.join('\n'), docTitle: (prefix + p.docTitle).slice(0, 120) } });
}
return out;

