// One output item per draft: pairs every Build Doc Text draft with the resolved Drive folder,
// so 'All of the above' writes one Google Doc per format into the SAME folder.
const folderId = $json.id;
if (!folderId) { throw new Error('No Drive folder id available - cannot write the draft(s).'); }
return $('Build Doc Text').all().map(d => ({ json: { folderId: folderId, docText: d.json.docText, docTitle: d.json.docTitle } }));

// Off-topic confirmation (2026-07-21). Form values come back keyed by fieldLabel, and a
// checkbox returns an ARRAY of the ticked option labels - the same shape Normalize Input
// already handles for 'Current News'.
const j = $input.first().json;
const norm = $('Normalize Input').first().json;
const ans = String(j['Write this article anyway?'] || '').trim().toLowerCase();
const joinRaw = j['Join DPDP and this topic'];
const joinDpdp = Array.isArray(joinRaw) ? joinRaw.length > 0 : (joinRaw !== undefined && joinRaw !== null && String(joinRaw).trim() !== '' && String(joinRaw).toLowerCase() !== 'false');
const proceed = ans === 'yes';
// Joining routes through the NORMAL grounded pipeline. The DPDP framing is appended because
// this string IS the retrieval query - those terms are what let hybrid search find real
// provisions for a subject that is otherwise off-corpus.
const ragTopic = (joinDpdp ? norm.topic + " - what India's DPDP Act 2023 and DPDP Rules 2025 require of it" : norm.topic).slice(0, 500);
const decision = !proceed ? 'stop' : (joinDpdp ? 'rag' : 'general');
return [{ json: Object.assign({}, norm, {
  topic: ragTopic,
  ragTopic: ragTopic,
  mode: joinDpdp ? 'dpdp' : 'general',
  joinDpdp: joinDpdp,
  decision: decision,
  errorMessage: 'Cancelled - the topic is not covered by the DPDP Act 2023 or the DPDP Rules 2025, and you chose not to write it.'
}) }];
